package eu.kanade.presentation.theme.colorscheme

import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.ui.graphics.Color

/**
 * Colors for Matrix theme, from Aniyomi via Komikku (Apache 2.0)
 * Original color scheme by LuftVerbot; the light scheme and bottom bar colors are Reikai's
 * M3 colors generated by Material Theme Builder (https://goo.gle/material-theme-builder-web)
 *
 * Key colors: primary 0xFF00FF00, secondary 0xFF00FF00, tertiary 0xFFFFFFFF
 */
internal object MatrixColorScheme : BaseColorScheme() {

    override val darkScheme = darkColorScheme(
        primary = Color(0xFF00FF00),
        onPrimary = Color(0xFFFAFAFA),
        primaryContainer = Color(0xFF00FF00),
        onPrimaryContainer = Color(0xFFFAFAFA),
        secondary = Color(0xFF00FF00),
        onSecondary = Color(0xFFFAFAFA),
        secondaryContainer = Color(0xFF00FF00),
        onSecondaryContainer = Color(0xFFFAFAFA),
        tertiary = Color(0xFFFFFFFF),
        onTertiary = Color(0xFF00FF00),
        tertiaryContainer = Color(0xFFFFFFFF),
        onTertiaryContainer = Color(0xFF00FF00),
        background = Color(0xFF111111),
        onBackground = Color(0xFFFFFFFF),
        surface = Color(0xFF111111),
        onSurface = Color(0xFFFFFFFF),
        surfaceVariant = Color(0xFF212121),
        onSurfaceVariant = Color(0xFFD8FFFFFF),
        surfaceTint = Color(0xFF00FF00),
        inverseSurface = Color(0xFFFAFAFA),
        inverseOnSurface = Color(0xFF313131),
        outline = Color(0xFF00FF00),
        inversePrimary = Color(0xFF007700),
        surfaceContainerLowest = Color(0xFF0B0B0B),
        surfaceContainerLow = Color(0xFF161616),
        surfaceContainer = Color(0xFF1A1A1A), // Navigation bar background
        surfaceContainerHigh = Color(0xFF202020),
        surfaceContainerHighest = Color(0xFF262626),
    )

    override val lightScheme = lightColorScheme(
        primary = Color(0xFF008F11),
        onPrimary = Color(0xFFFFFFFF),
        primaryContainer = Color(0xFF008F11),
        onPrimaryContainer = Color(0xFFFFFFFF),
        inversePrimary = Color(0xFF00FF41),
        secondary = Color(0xFF008F11), // Unread badge
        onSecondary = Color(0xFFFFFFFF), // Unread badge text
        secondaryContainer = Color(0xFF008F11), // Navigation bar selector pill & progress indicator (remaining)
        onSecondaryContainer = Color(0xFFFFFFFF), // Navigation bar selector icon
        tertiary = Color(0xFF003B00), // Downloaded badge
        onTertiary = Color(0xFFFFFFFF), // Downloaded badge text
        tertiaryContainer = Color(0xFFDCEBDC),
        onTertiaryContainer = Color(0xFF0D1F0D),
        background = Color(0xFFF3FAF3),
        onBackground = Color(0xFF0D1F0D),
        surface = Color(0xFFF3FAF3),
        onSurface = Color(0xFF0D1F0D),
        surfaceVariant = Color(0xFFDCEBDC), // Navigation bar background (ThemePrefWidget)
        onSurfaceVariant = Color(0xFF3E5A3E),
        surfaceTint = Color(0xFF008F11),
        inverseSurface = Color(0xFF1E2B1E),
        inverseOnSurface = Color(0xFFEEF6EE),
        outline = Color(0xFF008F11),
        surfaceContainerLowest = Color(0xFFFFFFFF),
        surfaceContainerLow = Color(0xFFEDF5ED),
        surfaceContainer = Color(0xFFE6F0E6), // Navigation bar background
        surfaceContainerHigh = Color(0xFFDFEADF),
        surfaceContainerHighest = Color(0xFFD8E4D8),
    )
}
